/* deriche.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "deriche.h"

/* Tunable blocking factor for the vertical passes.
 * This is the number of columns processed together; it should be
 * chosen such that (DERICHE_COL_BLOCK * sizeof(DATA_TYPE)) fits
 * comfortably in L1/L2 cache along with the row working set. */
#ifndef DERICHE_COL_BLOCK
# define DERICHE_COL_BLOCK 32
#endif


/* Array initialization. */
static
void init_array (int w, int h, DATA_TYPE* alpha,
		 DATA_TYPE POLYBENCH_2D(imgIn,W,H,w,h),
		 DATA_TYPE POLYBENCH_2D(imgOut,W,H,w,h))
{
  int i, j;

  *alpha=0.25; //parameter of the filter

  //input should be between 0 and 1 (grayscale image pixel)
  for (i = 0; i < w; i++)
     for (j = 0; j < h; j++)
	imgIn[i][j] = (DATA_TYPE) ((313*i+991*j)%65536) / 65535.0f;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int w, int h,
		 DATA_TYPE POLYBENCH_2D(imgOut,W,H,w,h))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("imgOut");
  for (i = 0; i < w; i++)
    for (j = 0; j < h; j++) {
      if ((i * h + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, imgOut[i][j]);
    }
  POLYBENCH_DUMP_END("imgOut");
  POLYBENCH_DUMP_FINISH;
}



/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* Original code provided by Gael Deest */
static void __attribute__((flatten, noinline))
kernel_deriche(int w, int h, DATA_TYPE alpha,
       DATA_TYPE POLYBENCH_2D(imgIn, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(imgOut, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y1, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y2, W, H, w, h)) {
    int i, j;

    /* Filter coefficients and temporaries.  These are computed once
     * outside of the main loops. */
    DATA_TYPE k;
    DATA_TYPE a1, a2, a3, a4, a5, a6, a7, a8;
    DATA_TYPE b1, b2, c1, c2;

#pragma scop
    /* Precompute exponentials and powers used in the coefficients. */
    const DATA_TYPE one = SCALAR_VAL(1.0);
    const DATA_TYPE two = SCALAR_VAL(2.0);

    const DATA_TYPE neg_alpha  = -alpha;
    const DATA_TYPE exp_malpha = EXP_FUN(neg_alpha);           /* e^{-α}   */
    const DATA_TYPE exp_m2alpha = EXP_FUN(neg_alpha * two);    /* e^{-2α}  */
    const DATA_TYPE exp_2alpha  = EXP_FUN(alpha * two);        /* e^{2α}   */

    k  = (one - exp_malpha) * (one - exp_malpha) /
         (one + two * alpha * exp_malpha - exp_2alpha);

    a1 = k;
    a2 = k * exp_malpha * (alpha - one);
    a3 = k * exp_malpha * (alpha + one);
    a4 = -k * exp_m2alpha;

    /* Vertical coefficients mirror the horizontal ones. */
    a5 = a1;
    a6 = a2;
    a7 = a3;
    a8 = a4;

    b1 =  POW_FUN(two, -alpha);
    b2 = -exp_m2alpha;
    c1 = c2 = SCALAR_VAL(1.0);

    /* Local aliases for loop bounds (may expand _PB_W/H macros). */
    const int Wn = _PB_W;
    const int Hn = _PB_H;

    /* 1. Horizontal pass: left -> right (produces y1). */
    for (i = 0; i < Wn; ++i) {
        DATA_TYPE * __restrict imgIn_row = imgIn[i];
        DATA_TYPE * __restrict y1_row    = y1[i];

        DATA_TYPE xm1 = SCALAR_VAL(0.0);
        DATA_TYPE ym1 = SCALAR_VAL(0.0);
        DATA_TYPE ym2 = SCALAR_VAL(0.0);

        for (j = 0; j < Hn; ++j) {
            DATA_TYPE x_curr = imgIn_row[j];
            DATA_TYPE y_curr = a1 * x_curr + a2 * xm1 + b1 * ym1 + b2 * ym2;

            y1_row[j] = y_curr;

            xm1 = x_curr;
            ym2 = ym1;
            ym1 = y_curr;
        }
    }

    /* 2. Horizontal pass: right -> left (produces y2). */
    for (i = 0; i < Wn; ++i) {
        DATA_TYPE * __restrict imgIn_row = imgIn[i];
        DATA_TYPE * __restrict y2_row    = y2[i];

        DATA_TYPE xp1 = SCALAR_VAL(0.0);
        DATA_TYPE xp2 = SCALAR_VAL(0.0);
        DATA_TYPE yp1 = SCALAR_VAL(0.0);
        DATA_TYPE yp2 = SCALAR_VAL(0.0);

        for (j = Hn - 1; j >= 0; --j) {
            DATA_TYPE y_curr = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;

            y2_row[j] = y_curr;

            xp2 = xp1;
            xp1 = imgIn_row[j];
            yp2 = yp1;
            yp1 = y_curr;
        }
    }

    /* 3. Combine horizontal results into intermediate imgOut. */
    for (i = 0; i < Wn; ++i) {
        DATA_TYPE * __restrict imgOut_row = imgOut[i];
        DATA_TYPE * __restrict y1_row     = y1[i];
        DATA_TYPE * __restrict y2_row     = y2[i];

        for (j = 0; j < Hn; ++j) {
            imgOut_row[j] = c1 * (y1_row[j] + y2_row[j]);
        }
    }

    /* 4. Vertical pass: top -> bottom (updates y1 from imgOut).
     *
     * Original code processes one column j at a time, scanning i from
     * top to bottom. That access pattern is severely strided in memory
     * because of the row-major layout [W][H].
     *
     * Here we block the columns: we keep the recurrence state (tm1,
     * ym1, ym2) for several columns at once and, for each row i, we
     * update all columns in the current block.  This makes the inner
     * loop traverse contiguous elements along the j-dimension, greatly
     * improving cache locality while preserving the exact dependency
     * order along i for every column.
     */
    {
        DATA_TYPE tm1_block[DERICHE_COL_BLOCK];
        DATA_TYPE ym1_block[DERICHE_COL_BLOCK];
        DATA_TYPE ym2_block[DERICHE_COL_BLOCK];

        for (int jb = 0; jb < Hn; jb += DERICHE_COL_BLOCK) {
            const int jb_end = (jb + DERICHE_COL_BLOCK < Hn) ? (jb + DERICHE_COL_BLOCK) : Hn;
            const int B = jb_end - jb;

            /* Initialize per-column recurrence state for this block. */
            for (int jj = 0; jj < B; ++jj) {
                tm1_block[jj] = SCALAR_VAL(0.0);
                ym1_block[jj] = SCALAR_VAL(0.0);
                ym2_block[jj] = SCALAR_VAL(0.0);
            }

            /* Sweep downward along i while updating all columns in the block. */
            for (i = 0; i < Wn; ++i) {
                DATA_TYPE * __restrict imgOut_row = imgOut[i];
                DATA_TYPE * __restrict y1_row     = y1[i];

                for (int jj = 0; jj < B; ++jj) {
                    const int j_col = jb + jj;

                    const DATA_TYPE prev_tm1 = tm1_block[jj];
                    const DATA_TYPE prev_ym1 = ym1_block[jj];
                    const DATA_TYPE prev_ym2 = ym2_block[jj];

                    const DATA_TYPE x_curr = imgOut_row[j_col];
                    const DATA_TYPE y_curr = a5 * x_curr
                                           + a6 * prev_tm1
                                           + b1 * prev_ym1
                                           + b2 * prev_ym2;

                    y1_row[j_col] = y_curr;

                    tm1_block[jj] = x_curr;
                    ym2_block[jj] = prev_ym1;
                    ym1_block[jj] = y_curr;
                }
            }
        }
    }

    /* 5. Vertical pass: bottom -> top (updates y2 from imgOut).
     *
     * Similar blocking strategy as above, but we traverse i from
     * bottom to top and use the a7–a8 coefficients.  Each column’s
     * recurrence along i still occurs in the exact same order as in
     * the original implementation; only independent columns are
     * interleaved for better locality.
     */
    {
        DATA_TYPE tp1_block[DERICHE_COL_BLOCK];
        DATA_TYPE tp2_block[DERICHE_COL_BLOCK];
        DATA_TYPE yp1_block[DERICHE_COL_BLOCK];
        DATA_TYPE yp2_block[DERICHE_COL_BLOCK];

        for (int jb = 0; jb < Hn; jb += DERICHE_COL_BLOCK) {
            const int jb_end = (jb + DERICHE_COL_BLOCK < Hn) ? (jb + DERICHE_COL_BLOCK) : Hn;
            const int B = jb_end - jb;

            /* Initialize per-column recurrence state for this block. */
            for (int jj = 0; jj < B; ++jj) {
                tp1_block[jj] = SCALAR_VAL(0.0);
                tp2_block[jj] = SCALAR_VAL(0.0);
                yp1_block[jj] = SCALAR_VAL(0.0);
                yp2_block[jj] = SCALAR_VAL(0.0);
            }

            /* Sweep upward along i while updating all columns in the block. */
            for (i = Wn - 1; i >= 0; --i) {
                DATA_TYPE * __restrict imgOut_row = imgOut[i];
                DATA_TYPE * __restrict y2_row     = y2[i];

                for (int jj = 0; jj < B; ++jj) {
                    const int j_col = jb + jj;

                    const DATA_TYPE xp1   = tp1_block[jj];
                    const DATA_TYPE xp2   = tp2_block[jj];
                    const DATA_TYPE yp1_l = yp1_block[jj];
                    const DATA_TYPE yp2_l = yp2_block[jj];

                    const DATA_TYPE y_curr = a7 * xp1
                                           + a8 * xp2
                                           + b1 * yp1_l
                                           + b2 * yp2_l;

                    y2_row[j_col] = y_curr;

                    tp2_block[jj] = xp1;
                    tp1_block[jj] = imgOut_row[j_col];
                    yp2_block[jj] = yp1_l;
                    yp1_block[jj] = y_curr;
                }
            }
        }
    }

    /* 6. Final combination of vertical results into imgOut. */
    for (i = 0; i < Wn; ++i) {
        DATA_TYPE * __restrict imgOut_row = imgOut[i];
        DATA_TYPE * __restrict y1_row     = y1[i];
        DATA_TYPE * __restrict y2_row     = y2[i];

        for (j = 0; j < Hn; ++j) {
            imgOut_row[j] = c2 * (y1_row[j] + y2_row[j]);
        }
    }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int w = W;
  int h = H;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(imgIn, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(imgOut, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(y1, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(y2, DATA_TYPE, W, H, w, h);


  /* Initialize array(s). */
  init_array (w, h, &alpha, POLYBENCH_ARRAY(imgIn), POLYBENCH_ARRAY(imgOut));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_deriche (w, h, alpha, POLYBENCH_ARRAY(imgIn), POLYBENCH_ARRAY(imgOut), POLYBENCH_ARRAY(y1), POLYBENCH_ARRAY(y2));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(w, h, POLYBENCH_ARRAY(imgOut)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(imgIn);
  POLYBENCH_FREE_ARRAY(imgOut);
  POLYBENCH_FREE_ARRAY(y1);
  POLYBENCH_FREE_ARRAY(y2);

  return 0;
}
