            const DATA_TYPE x = imgIn_[i][j];
            const DATA_TYPE y = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;
            y1_[i][j] = y;
            xm1 = x;
            ym2 = ym1;
            ym1 = y;
