        /* Backward recursive filter along row i (original second loop). */
        xp1 = SCALAR_VAL(0.0);
        xp2 = SCALAR_VAL(0.0);
        yp1 = SCALAR_VAL(0.0);
        yp2 = SCALAR_VAL(0.0);
        for (int j = H_ - 1; j >= 0; j--) {
