            for (int j = jj; j < j_end; j++) {
                const DATA_TYPE prev_tp1 = tp1_col[j];
                const DATA_TYPE prev_tp2 = tp2_col[j];
                const DATA_TYPE prev_yp1 = yp1_col[j];
                const DATA_TYPE prev_yp2 = yp2_col[j];

                const DATA_TYPE y = a7 * prev_tp1 + a8 * prev_tp2
                                    + b1 * prev_yp1 + b2 * prev_yp2;
                y2_[i][j] = y;

                tp2_col[j] = prev_tp1;
                tp1_col[j] = imgOut_[i][j];
                yp2_col[j] = prev_yp1;
                yp1_col[j] = y;
