}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int w, int h,
		 DATA_TYPE POLYBENCH_2D(imgOut,W,H,w,h))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("imgOut");
  for (i = 0; i < w; i++)
    for (j = 0; j < h; j++) {
      if ((i * h + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, imgOut[i][j]);
    }
  POLYBENCH_DUMP_END("imgOut");
  POLYBENCH_DUMP_FINISH;
}



/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* Original code provided by Gael Deest
 *
 * Optimized version:
 *  - Horizontal passes fused per row to improve temporal locality.
 *  - Vertical passes rewritten to use per-column state arrays but
 *    traverse the image in row-major order, greatly improving cache
 *    locality while preserving the exact recurrences.
 *  - Backward passes are fused with the combining steps to avoid
 *    storing intermediate y2 arrays, reducing memory traffic.
 *  - Read-only filter coefficients are hoisted and common
 *    exponentials are computed once.
 */
static
void kernel_deriche[[gnu::flatten, gnu::noinline]](int w, int h, DATA_TYPE alpha,
       DATA_TYPE POLYBENCH_2D(imgIn, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(imgOut, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y1, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y2, W, H, w, h))
{
  /* w, h and y2 are unused explicitly below (we rely on _PB_W/_PB_H
   * and do not need to materialize y2), but they are kept in the
   * signature for compatibility with the original driver code. */
  (void)w;
  (void)h;
  (void)y2;

  /* Use the PolyBench loop bounds so the semantics w.r.t. the
   * benchmark harness are unchanged. */
  const int W_ = _PB_W;
  const int H_ = _PB_H;

  /* Create explicit, restrict-qualified 2D aliases.  This helps the
   * compiler reason about aliasing and index arithmetic. */
  DATA_TYPE (* __restrict imgIn_ )[H_] = (DATA_TYPE (*)[H_]) imgIn;
  DATA_TYPE (* __restrict imgOut_)[H_] = (DATA_TYPE (*)[H_]) imgOut;
  DATA_TYPE (* __restrict y1_    )[H_] = (DATA_TYPE (*)[H_]) y1;

  DATA_TYPE xm1, ym1, ym2;
  DATA_TYPE xp1, xp2;
  DATA_TYPE yp1, yp2;

  DATA_TYPE k;
  DATA_TYPE a1, a2, a3, a4, a5, a6, a7, a8;
  DATA_TYPE b1, b2, c1, c2;

#pragma scop
  /* Precompute exponentials that are reused in several coefficients.
   * This preserves the exact numerical behavior of the original code
   * (same calls, just common-subexpression elimination made explicit). */
  const DATA_TYPE exp_neg_alpha  = EXP_FUN(-alpha);
  const DATA_TYPE exp_neg_2alpha = EXP_FUN(SCALAR_VAL(-2.0) * alpha);
  const DATA_TYPE exp_pos_2alpha = EXP_FUN(SCALAR_VAL( 2.0) * alpha);

  /* Filter coefficients (unchanged formulas). */
  k  = (SCALAR_VAL(1.0) - exp_neg_alpha) * (SCALAR_VAL(1.0) - exp_neg_alpha)
     / (SCALAR_VAL(1.0)
        + SCALAR_VAL(2.0) * alpha * exp_neg_alpha
        - exp_pos_2alpha);

  a1 = a5 = k;
  a2 = a6 = k * exp_neg_alpha * (alpha - SCALAR_VAL(1.0));
  a3 = a7 = k * exp_neg_alpha * (alpha + SCALAR_VAL(1.0));
  a4 = a8 = -k * exp_neg_2alpha;

  b1 = POW_FUN(SCALAR_VAL(2.0), -alpha);
  b2 = -exp_neg_2alpha;

  c1 = c2 = SCALAR_VAL(1.0);

  /* ------------------------------------------------------------------
   * 1. Horizontal filtering (along j) – row-major friendly
   *
   * We fuse the original three horizontal loops:
   *   - forward pass (y1)
   *   - backward pass (y2)
   *   - combination into imgOut
   * into a single outer loop over rows. For each row:
   *   - compute the forward recursion into y1_[i][*]
   *   - compute the backward recursion while *directly* forming
   *     imgOut_[i][*] = c1 * (y1_[i][*] + backward)
   * This avoids materializing y2 for the horizontal stage while
   * preserving the exact recurrences per row.
   * ------------------------------------------------------------------ */
  for (int i = 0; i < W_; ++i)
  {
    DATA_TYPE* in_row  = imgIn_ [i];
    DATA_TYPE* out_row = imgOut_[i];
    DATA_TYPE* y1_row  = y1_    [i];

    /* Forward recursive pass on row i. */
    xm1 = SCALAR_VAL(0.0);
    ym1 = SCALAR_VAL(0.0);
    ym2 = SCALAR_VAL(0.0);

    for (int j = 0; j < H_; ++j) {
      const DATA_TYPE x = in_row[j];
      const DATA_TYPE y = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;

      y1_row[j] = y;

      xm1 = x;
      ym2 = ym1;
      ym1 = y;
    }

    /* Backward recursive pass on row i, fused with combination. */
    xp1 = SCALAR_VAL(0.0);
    xp2 = SCALAR_VAL(0.0);
    yp1 = SCALAR_VAL(0.0);
    yp2 = SCALAR_VAL(0.0);

    for (int j = H_ - 1; j >= 0; --j) {
      const DATA_TYPE xp0 = in_row[j];
      const DATA_TYPE yb  = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;

      /* Combine forward and backward horizontal contributions. */
      out_row[j] = c1 * (y1_row[j] + yb);

      xp2 = xp1;
      xp1 = xp0;
      yp2 = yp1;
      yp1 = yb;
    }
  }

  /* ------------------------------------------------------------------
   * 2. Vertical filtering (along i) – implemented in row-major order
   *
   * Original code:
   *   for each column j:
   *     run a forward vertical recursion over i into y1
   *   for each column j:
   *     run a backward vertical recursion over i into y2
   *   combine y1 and y2 into imgOut
   *
   * This is cache-unfriendly because accesses are strided in memory
   * (the first index i varies fastest while rows are contiguous).
   *
   * Here we preserve the *per-column* recurrences exactly, but we
   * traverse the image row by row. We keep separate recursion state
   * for each column j in small 1D arrays. This gives contiguous
   * accesses in j while maintaining the same mathematical result.
   * We also fuse the backward pass with the final combination, so we
   * never need to materialize a vertical y2 array.
   * ------------------------------------------------------------------ */

  /* Forward vertical pass: maintain tm1/ym1/ym2 per column. */
  {
    DATA_TYPE tm1_col[H_];
    DATA_TYPE ym1_col[H_];
    DATA_TYPE ym2_col[H_];

    /* Initialize all column states exactly as in the original code
     * (tm1 = ym1 = ym2 = 0 at the top of each column). */
    for (int j = 0; j < H_; ++j) {
      tm1_col[j] = SCALAR_VAL(0.0);
      ym1_col[j] = SCALAR_VAL(0.0);
      ym2_col[j] = SCALAR_VAL(0.0);
    }

    for (int i = 0; i < W_; ++i) {
      DATA_TYPE* out_row = imgOut_[i];
      DATA_TYPE* y1_row  = y1_    [i];

      for (int j = 0; j < H_; ++j) {
        const DATA_TYPE x = out_row[j];
        const DATA_TYPE y = a5 * x
                          + a6 * tm1_col[j]
                          + b1 * ym1_col[j]
                          + b2 * ym2_col[j];

        y1_row[j] = y;

        tm1_col[j] = x;
        ym2_col[j] = ym1_col[j];
        ym1_col[j] = y;
      }
    }
  }

  /* Backward vertical pass, fused with final combination into imgOut_. */
  {
    DATA_TYPE tp1_col[H_];
    DATA_TYPE tp2_col[H_];
    DATA_TYPE yp1_col[H_];
    DATA_TYPE yp2_col[H_];

    /* Initialize per-column backward states (tp1 = tp2 = yp1 = yp2 = 0). */
    for (int j = 0; j < H_; ++j) {
      tp1_col[j] = SCALAR_VAL(0.0);
      tp2_col[j] = SCALAR_VAL(0.0);
      yp1_col[j] = SCALAR_VAL(0.0);
      yp2_col[j] = SCALAR_VAL(0.0);
    }

    for (int i = W_ - 1; i >= 0; --i) {
      DATA_TYPE* out_row = imgOut_[i];  /* still holds horizontally filtered data */
      DATA_TYPE* y1_row  = y1_    [i];  /* vertical forward results */

      for (int j = 0; j < H_; ++j) {
        /* Backward vertical recurrence for column j. */
        const DATA_TYPE yb = a7 * tp1_col[j]
                           + a8 * tp2_col[j]
                           + b1 * yp1_col[j]
                           + b2 * yp2_col[j];

        /* Update per-column state using the original (horizontally
         * filtered) imgOut value at (i,j). We read it before
         * overwriting out_row[j], so the recurrence sees exactly the
         * same data as in the original column-wise implementation. */
        const DATA_TYPE x = out_row[j];
        tp2_col[j] = tp1_col[j];
        tp1_col[j] = x;
        yp2_col[j] = yp1_col[j];
        yp1_col[j] = yb;

        /* Final output: sum of forward and backward vertical passes. */
        out_row[j] = c2 * (y1_row[j] + yb);
      }
    }
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int w = W;
  int h = H;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(imgIn, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(imgOut, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(y1, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(y2, DATA_TYPE, W, H, w, h);


  /* Initialize array(s). */
  init_array (w, h, &alpha, POLYBENCH_ARRAY(imgIn), POLYBENCH_ARRAY(imgOut));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_deriche (w, h, alpha, POLYBENCH_ARRAY(imgIn), POLYBENCH_ARRAY(imgOut),
                  POLYBENCH_ARRAY(y1), POLYBENCH_ARRAY(y2));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(w, h, POLYBENCH_ARRAY(imgOut)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(imgIn);
  POLYBENCH_FREE_ARRAY(imgOut);
  POLYBENCH_FREE_ARRAY(y1);
  POLYBENCH_FREE_ARRAY(y2);

  return 0;
}
